"""Form Three Geography Term One: lesson rows plus guided practicals 4, 6 and 8.
Further-study row 2 is not treated as a separate taught lesson.
"""
from codex_support import *
from lessonlib import num, worked
F=fact
def unit(n,title,note,case,method,facts,**kw):
    concept_lesson("geography","g3-",n,title,note,case,method,facts,"earth",**kw)

unit(1,"Earth: shape, size and evidence",
 "Earth is approximately spherical, with a slight equatorial bulge and flattening at the poles. Its mean radius is about {6371} km; its equatorial diameter is about {12756} km. A globe models this shape; a flat map represents selected features with some distortion. Evidence includes observations from space, a curved shadow during a lunar eclipse and changes in visible stars with latitude. A single local horizon observation needs careful interpretation because hills and atmospheric effects matter. Circumnavigation is consistent with the shape, but modern direct observation gives stronger evidence than an isolated travel story.",
 "A pupil in Buea can compare a globe with a flat wall map. The map is convenient for routes, while the globe better represents the whole planet's shape. Neither is the planet itself. A ship disappearing hull-first over a clear sea can illustrate curvature, but one obscured view should not be treated as a complete proof by itself.",
 "Separate an observation from the conclusion it supports. Use several independent lines of evidence. Do not confuse spherical with perfectly smooth: mountains and valleys are small surface irregularities relative to the planet. State whether a measurement is approximate rather than pretending every model is exact.",[
 F("oblate shape","a near-sphere slightly flattened at the poles","A model shows a small equatorial bulge.","Earth is a perfectly flat circular plate.","The global evidence supports a near-spherical planet with slight polar flattening."),
 F("globe","a reduced model of Earth's whole shape","A class uses a spherical model to compare hemispheres.","A globe has no scale because it is round.","A globe is a scaled model, not the full-sized planet."),
 F("map projection","a method of representing a curved surface on a plane","A wall map stretches some regions when the globe is flattened.","Every flat world map preserves every shape, area and distance exactly.","Flattening a curved surface introduces trade-offs and distortion."),
 F("supporting evidence","observations that help test an explanation","Images from space and a lunar-eclipse shadow agree with curvature.","One obstructed view disproves every independent observation.","Assess several lines of evidence and the conditions of each observation.")])

unit(3,"Latitude and longitude",
 "Latitude measures angular position north or south of the Equator. Longitude measures angular position east or west of the Greenwich meridian. Parallels join places of equal latitude; meridians connect the poles. Write latitude first and include the hemisphere. A coordinate without its hemisphere can describe more than one location. Cameroon is in the northern and eastern hemispheres, but classroom points on an invented grid are not surveyed locations of actual towns.",
 "A learner locating a place near Buea first identifies the Equator and the Greenwich reference, then reads north/south and east/west separately. On a graticule, trace the place to the labelled lines. Do not swap a parallel with a meridian just because both appear as straight lines on a flat diagram.",
 "Identify the reference line, read the angle and add the hemisphere. If a point is between marked lines, estimate consistently with the scale. A grid reference based on eastings and northings is a different system from a latitude-longitude coordinate.",[
 F("latitude","angular position north or south of the Equator","A coordinate gives a place's northward angle from the Equator.","Latitude is measured east from Greenwich.","East/west from Greenwich describes longitude, not latitude."),
 F("longitude","angular position east or west of Greenwich","A coordinate gives a place's eastward angle from the prime meridian.","Longitude is measured north from the Equator.","North/south from the Equator describes latitude."),
 F("parallel","a line joining equal latitudes","A learner follows the Equator around a globe.","Every parallel passes through both poles.","Meridians connect the poles; parallels circle at constant latitude."),
 F("meridian","a line joining the poles at a given longitude","A learner traces Greenwich's reference line from pole to pole.","A meridian is a small circle parallel to the Equator.","A meridian runs between poles rather than parallel to the Equator.")])

def coordinate(n,axis):
    return num(f"g3-{n}-{axis}",2,"Read point A on the graticule. Give its "+axis+" in degrees "+("north" if axis=="latitude" else "east")+".","la" if axis=="latitude" else "lo",
      ["Read the "+("horizontal parallel" if axis=="latitude" else "vertical meridian")+" through A.","The angle is {answer} degrees "+("north" if axis=="latitude" else "east")+"."],
      vars={"la":{"pick":[10,20,30]},"lo":{"pick":[10,20,30]}},figure="graticule(0,0,10,[['A',la,lo]])",unit="degrees "+("north" if axis=="latitude" else "east"),sources=["earth"])

for n,title,axis in [(4,"Practical preparation: reading a geographical coordinate","latitude"),(6,"Practical preparation: locating a longitude","longitude")]:
    unit(n,title,
     "To locate a point, read latitude and longitude from their reference lines and include the hemispheres. This guided practical uses an invented graticule on screen. Start with the parallel through the point, then the meridian. Check the spacing of the labelled lines before estimating an intermediate value. Record the coordinate in your exercise book with latitude first. The practice checks written map reading, not the accuracy of a real field survey.",
     "The diagram marks A on an invented grid. All points used here lie north of the Equator and east of Greenwich. Trace A horizontally to the latitude labels, and vertically to the longitude labels. Because each point lies on labelled lines, no estimate is needed in these examples. These coordinates are not being presented as actual locations of named Cameroonian towns.",
     "Write the reference line and hemisphere beside each value. Check that the value you read belongs to the correct axis. For an actual map, consult its key and projection as well. Swapping the two values moves the point and changes its meaning.",[
     F("latitude reading","the north/south angle read from the parallel through a point","A learner follows A's horizontal line to the northward labels.","Read longitude labels to obtain latitude.","Use the parallel's latitude label, not the meridian's longitude label."),
     F("longitude reading","the east/west angle read from the meridian through a point","A learner follows A's vertical line to the eastward labels.","Read latitude labels to obtain longitude.","Use the meridian's longitude label, not the parallel's latitude label."),
     F("hemisphere label","the direction that completes an angular coordinate","A learner writes north or south after the latitude angle.","A bare angle always gives one unique global location.","Without direction and the other coordinate, a bare angle is incomplete."),
     F("coordinate order","latitude followed by longitude","A learner records the north/south value before the east/west value.","The two angles may always be swapped without changing the location.","Latitude and longitude perform different roles, so their order matters.")],prerequisites=[3],replacement={2:coordinate(n,axis),3:coordinate(n,"longitude" if axis=="latitude" else "latitude")},learn_figure="graticule(0,0,10,[['A',20,30]])")

unit(5,"Great circles and the International Date Line",
 "A great circle is formed when a plane through Earth's centre cuts its surface, dividing the sphere into equal hemispheres. The Equator is a great circle; a meridian paired with its opposite also forms one. Other parallels are small circles. On a sphere, the shorter great-circle arc gives a shortest surface route between suitable points. The International Date Line is a civil-date boundary broadly near the opposite meridian to Greenwich, with deviations. Crossing it westward adds a day; eastward subtracts a day.",
 "A route drawn straight on a flat world map is not necessarily the shortest route on a globe. A traveller crossing the Date Line must adjust the calendar as well as the clock. A time difference near midnight can also change a date without crossing the line, so keep the two reasons for date changes distinct.",
 "Ask whether the cutting plane passes through the centre. For date exercises, identify travel direction and state the adopted line convention. Actual civil boundaries and standard-time decisions are irregular; do not treat the diagram as an exact map of present national rules.",[
 F("great circle","a circle dividing a sphere into equal hemispheres","The Equator's plane passes through Earth's centre.","Every parallel is a great circle.","Only a parallel through the centre, the Equator, is a great circle."),
 F("small circle","a circle whose plane does not pass through the sphere's centre","A parallel north of the Equator divides unequal surface portions.","A small circle must divide Earth into equal hemispheres.","Its offset plane does not cut through the centre."),
 F("westward date-line crossing","a crossing convention that advances the calendar by a day","An idealised traveller crosses the Date Line toward the west.","Westward Date Line travel always subtracts a calendar day.","Under the standard crossing convention, westward travel adds a day."),
 F("eastward date-line crossing","a crossing convention that moves the calendar back a day","An idealised traveller crosses the Date Line toward the east.","Eastward Date Line travel always adds a calendar day.","Under the standard crossing convention, eastward travel subtracts a day.")])

unit(7,"Local time, standard time and zones",
 "Longitude affects local solar time because Earth rotates. Places farther east are ahead of places farther west in the ideal longitude calculation. Earth turns through {360} degrees in about {24} hours, so {15} degrees corresponds to {1} hour and {1} degree to {4} minutes. Standard time is an adopted common time for a region, rather than a different clock for every meridian. Real civil zones follow political decisions and may differ from ideal equal-width zones.",
 "For an exercise, suppose local time at Greenwich is {720} minutes after midnight. At {15} degrees east the ideal local solar time is {780} minutes after midnight. The example illustrates rotation, not a statement that every country on that meridian uses the same current civil clock. Always distinguish a theoretical longitude exercise from a real journey timetable.",
 "Calculate the longitude difference, convert degrees to minutes and choose the sign: east ahead, west behind. Check whether the resulting minutes lie outside the current day. When asked about a real standard zone, use the stated offset rather than silently replacing it with longitude.",[
 F("local solar time","time related to the Sun at a particular longitude","An ideal calculation gives different noon times at different meridians.","Every longitude has local solar noon at the same instant.","Rotation brings different meridians toward the Sun at different times."),
 F("standard time","a common clock time adopted for a region","Several towns use a shared official clock despite different longitudes.","Standard time must differ at every street corner.","Its purpose is a shared regional convention rather than a separate solar clock everywhere."),
 F("east ahead","the sign convention that adds time toward greater eastern longitude","A theoretical point east of Greenwich reaches solar noon earlier.","Moving east in a longitude calculation always subtracts time.","Eastward longitude is ahead, so add the corresponding time difference."),
 F("ideal time zone","a simplified longitudinal band used in teaching time differences","A classroom globe divides an ideal day into equal angular bands.","Every actual civil border follows an ideal meridian exactly.","Civil zones can depart from the simplified angular model.")],replacement={3:num("g3-7-offset",2,"Two ideal meridians differ by {d} degrees. Find their local-time difference in minutes.","d*4",["Each degree corresponds to {4} minutes.","{d} × {4} = {answer} minutes."],vars={"d":{"int":[1,30]}},unit="minutes",sources=["earth"],misc=[("hours","d/15","That gives hours, but the question asks for minutes."),("divide","d/4","Multiply degrees by minutes per degree; do not divide.")])})

unit(8,"Practical preparation: calculating time and date",
 "A time-and-date exercise needs both an offset and a calendar check. Work in minutes after midnight to avoid mixing hours and minutes. Add the eastward time difference or subtract the westward difference. A result at or beyond the next midnight belongs to the following day; a negative result belongs to the preceding day. This guided practical uses ideal meridians, not current civil-zone regulations. State both the clock result and any date change when requested.",
 "A hypothetical point east of Greenwich is ahead. If the starting time is late at night, adding the offset may cross midnight. A point west can instead fall on the previous day when the starting time is early. In an exercise book, separate longitude difference, time offset, adjusted minutes and date change into labelled steps.",
 "Do not discard a negative sign before deciding the date. Reduce the clock value to one day only after recording whether the calculation crossed midnight. A Date Line journey and an ordinary offset calculation need careful interpretation of the convention stated in the question.",[
 F("time offset","the signed time difference applied to a starting time","A learner adds an eastern meridian's difference to Greenwich time.","An offset can be ignored whenever it is inconvenient.","The offset is what connects the two times in the exercise."),
 F("following day","the calendar result when a calculation passes the next midnight","An evening time plus an eastern offset exceeds a full day's minutes.","Passing the next midnight leaves the date unchanged.","A complete day crossed advances the date."),
 F("preceding day","the calendar result when a calculation goes before the starting midnight","An early time minus a western offset produces negative minutes.","A negative adjusted minute value means the next day.","Going backward across midnight reaches the previous day."),
 F("clock normalisation","expressing adjusted time within a single day's clock","A learner keeps the date change separate while reducing the clock time.","Reducing a clock value proves that no date change occurred.","Clock display and calendar day must be recorded separately.")],prerequisites=[7],replacement={2:num("g3-8-time",2,"Greenwich local time is {clock(t)}. An ideal point lies {lon(to)}. Give the adjusted time in minutes after the starting midnight, before reducing it to a clock display.","t+to*4",["East adds time; west subtracts.","{t} + ({to} × {4}) = {answer} minutes."],vars={"t":{"pick":[30,720,1410]},"to":{"pick":[-30,0,30]}},signed=True,unit="minutes",sources=["earth"]),3:num("g3-8-date",2,"Starting at {clock(t)} in Greenwich local time, calculate the day change at {lon(to)}: use {-1} for previous day, {0} for same day, {1} for next day.","m < 0 ? -1 : m >= 1440 ? 1 : 0",["Adjusted minutes = {t} + ({to} × {4}) = {m}.","Compare with {0} and {1440}; the day-change code is {answer}."],vars={"t":{"pick":[30,720,1410]},"to":{"pick":[-30,0,30]},"m":{"expr":"t+to*4"}},signed=True,sources=["earth"])})

unit(9,"Earth's rotation and its effects",
 "Rotation is Earth's turning about its axis, approximately once per day. As a place turns into and out of sunlight, it experiences day and night. The apparent daily movement of the Sun across the sky is mainly a result of this rotation. Longitude-related local-time differences and the Coriolis effect are other consequences. Rotation is different from revolution around the Sun. The model used here treats the Sun's incoming rays as parallel.",
 "On the diagram, a town on the side facing the Sun is in daylight. A town turning toward the illuminated side experiences sunrise; one turning away experiences sunset. A pupil in Cameroon sees the daily change between light and darkness, but should not infer from that observation that the Sun travels around Earth each day.",
 "Identify the axis and direction of turning. Locate the lit half before deciding whether a marked town is in day or night. State which movement explains the effect: daily turning is rotation, while the yearly orbit is revolution.",[
 F("rotation","Earth's turning about its axis","A marked town moves from the lit side to the dark side as the globe spins.","Rotation means Earth's yearly journey around the Sun.","The yearly journey is revolution; rotation is spinning about the axis."),
 F("daylight","the state of facing the Sun's illumination","A town lies on the illuminated half of the diagram.","Every point on Earth is in daylight simultaneously.","Only part of the rotating planet faces sunlight at once."),
 F("sunrise","a place turning into the illuminated part of Earth","A marked town enters the sunlit half as the globe turns.","Sunrise is a town turning from daylight into darkness.","That transition is sunset, not sunrise."),
 F("sunset","a place turning away from the illuminated part","A marked town moves from the sunlit side into darkness.","Sunset proves the Sun has stopped emitting light.","The local change follows Earth's turning, not the Sun switching off.")],learn_figure="dayNight(180)")

unit(10,"Earth's revolution, tilt and seasons",
 "Revolution is Earth's orbit around the Sun. Together with the tilt of the axis, it changes the angle of incoming sunlight and the duration of daylight through the year. This produces opposite seasonal tendencies in the northern and southern hemispheres. Seasons are not explained simply by changing distance from the Sun. Tropical Cameroon commonly describes rainfall seasons rather than copying every temperate seasonal label. Local rainfall also depends on atmospheric conditions; an orbit diagram alone is not a full account of Cameroon's rainfall.",
 "When the northern hemisphere tilts toward the Sun, sunlight is generally more direct there and days are longer away from the Equator. The southern hemisphere has the opposite tendency. Near the Equator, seasonal daylight variation is smaller. A learner should connect the global mechanism to local conditions without claiming that every place has identical seasons.",
 "Track the same tilted axis around the orbit while keeping its direction approximately parallel in the diagram. Compare sunlight angle and daylight duration. Distinguish the daily cycle from the yearly one, and avoid using Earth's distance as the principal explanation of opposite hemispheric seasons.",[
 F("revolution","Earth's orbital movement around the Sun","A model carries Earth around a yearly path.","Revolution is only a globe spinning in place.","Spinning is rotation; revolution is the orbital movement."),
 F("axial tilt","the inclination that changes seasonal illumination during revolution","The northern hemisphere leans toward the Sun during part of the orbit.","Opposite hemispheric seasons are caused only by both hemispheres changing their distance together.","Tilt changes how the hemispheres receive sunlight in opposite ways."),
 F("daylight duration","the length of time a place remains illuminated","A hemisphere tilted sunward has longer days in its summer season away from the Equator.","The length of daylight is identical at every latitude throughout the year.","Latitude and season affect daylight duration."),
 F("local seasonal pattern","a region's experienced annual weather cycle","A Cameroonian class distinguishes wet and dry periods when discussing its locality.","Every Cameroonian locality must copy a temperate four-season calendar exactly.","Local rainfall patterns need local climatic explanation rather than identical imported labels.")])

LAYERS=json.dumps('<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Schematic Earth layers, not to scale" viewBox="0 0 340 220"><circle cx="112" cy="110" r="98" fill="#877b67"/><circle cx="112" cy="110" r="91" fill="#bb8150"/><circle cx="112" cy="110" r="54" fill="#e5b24c"/><circle cx="112" cy="110" r="25" fill="#f5d98a"/><g font-family="sans-serif" font-size="12" fill="currentColor"><text x="218" y="28">crust (thin)</text><text x="218" y="70">mantle</text><text x="218" y="114">outer core</text><text x="218" y="158">inner core</text><text x="12" y="216">Schematic: not to scale</text></g><g stroke="currentColor"><path d="M150 20H215M185 65H215M160 110H215M130 125L210 155"/></g></svg>')
unit(11,"The internal structure of Earth",
 "Earth's main compositional layers are crust, mantle and core. The crust is the thin outer layer; the mantle beneath it is mostly solid rock that can flow very slowly over geological time. The core is largely iron-rich material: its outer part is liquid and its inner part solid. The lithosphere is a mechanical layer including crust and uppermost mantle, not a synonym for crust alone. Much evidence comes from seismic waves and other indirect observations, not a borehole reaching the core.",
 "A schematic cross-section helps a class in Buea distinguish layers, but the diagram is not to scale. The thin crust would otherwise be difficult to show. Do not interpret the whole mantle as an open underground sea of liquid lava. Different temperatures, pressures and material properties explain why layers behave differently.",
 "State whether a classification concerns composition or mechanical behaviour. Identify crust, mantle, outer core and inner core without swapping solid and liquid. A drawing illustrates a model; examine the observations supporting that model rather than treating coloured bands as direct photographs of the interior.",[
 F("crust","Earth's thin outer compositional layer","A rock sample is collected from the planet's outer surface.","The crust alone includes the entire mantle.","Crust and mantle are distinct compositional layers."),
 F("mantle","mostly solid rock below the crust that can flow slowly over long times","A model explains slow deformation below the rigid outer shell.","The whole mantle is liquid lava.","The mantle is predominantly solid, though it can deform slowly."),
 F("outer core","the liquid part of the iron-rich core","A model places a liquid metallic layer around the inner core.","The outer core is the rocky continental crust.","The outer core is deep metallic material, not surface crust."),
 F("inner core","the solid central part of the core","A model identifies the solid centre below the liquid outer core.","Inner and outer core must both be liquid.","The inner core is solid while the outer core is liquid.")],learn_figure=LAYERS)

unit(12,"Rocks and the rock cycle",
 "A rock is an aggregate of minerals or other natural solid material. Igneous rocks form when molten material cools and solidifies. Sedimentary rocks form through accumulation and consolidation of sediment, or other sedimentary processes. Metamorphic rocks form when existing rock changes under heat, pressure or fluids without melting completely. The rock cycle links formation, weathering, erosion, deposition, burial, change and melting. It has several pathways, not one compulsory route for every rock.",
 "A Cameroonian class may compare basalt from a volcanic area with layered sedimentary material and a metamorphic sample supplied by a teacher. Observation helps suggest a classification, but colour alone is not decisive. Ask about texture, minerals and how the sample formed. A rock can pass through several changes over long geological times.",
 "Classify by formation, then use observations as supporting evidence. Do not call any heated rock igneous unless melting and solidification are involved. Distinguish transport from deposition: moving material and laying it down are different stages.",[
 F("igneous rock","rock formed by cooling and solidification of molten material","Lava cools into solid basalt.","All rocks with layers must have crystallised from lava.","Layering alone does not establish molten origin; ask how the rock formed."),
 F("sedimentary rock","rock formed by sedimentary accumulation or related processes","Deposited grains are compacted and cemented.","Sediment must melt completely before forming sedimentary rock.","Compaction and cementation can form rock without complete melting."),
 F("metamorphic rock","existing rock changed without complete melting","Heat and pressure alter an existing rock while it remains largely solid.","Metamorphism always requires total melting.","Complete melting leads toward igneous formation on cooling, not solid-state metamorphism."),
 F("rock cycle","linked processes that transform rocks along different pathways","An existing rock weathers, is buried or melts under different conditions.","Every rock must follow one identical fixed sequence.","Different histories follow different pathways in the cycle.")])

unit(13,"Continental drift: evidence and limitations",
 "Continental drift proposes that continents have changed position over geological time. Wegener assembled evidence including the broad fit of continental margins, matching fossil distributions and corresponding rocks and ancient climatic indicators. Pangaea names a former supercontinent in this account. The early proposal lacked a convincing mechanism accepted at the time. Later seafloor and plate evidence helped develop plate tectonics. A similar outline alone is suggestive, not the entire argument.",
 "A learner compares continental margins across the Atlantic and then asks whether fossils and rock patterns also correspond. Several independent observations can support a reconstruction better than one jigsaw resemblance. Cameroon is part of the African plate framework, but an exact reconstruction needs geological evidence rather than simply moving modern political borders on paper.",
 "Separate the proposal, the supporting observations and the later mechanism. Use geological rather than national boundaries when considering continental history. Do not describe the early theory's incomplete mechanism as proof that every observation it used was worthless.",[
 F("continental drift","change in continental positions over geological time","A reconstruction places now-separated continental masses together in the past.","Continental drift concerns daily changes in national borders.","The concept concerns geological land masses over long times, not political administration."),
 F("Pangaea","a former supercontinent in continental reconstructions","A model joins major continental masses into one ancient landmass.","Pangaea is the present name of a single Cameroonian town.","Pangaea refers to an ancient continental configuration."),
 F("corresponding evidence","independent matching geological or fossil patterns across separated land masses","Similar fossil and rock patterns are compared across an ocean.","The coastline outline is the only evidence ever considered.","Fossils, rocks and ancient climate indicators provide additional lines of evidence."),
 F("mechanism problem","the difficulty of explaining what could move the continents in the early proposal","A reviewer asks how the proposed movement would occur.","Evidence for positions automatically explains the force causing movement.","A reconstruction and a physical mechanism answer different questions.")])

unit(14,"Plate tectonics",
 "Plate tectonics explains movement of rigid lithospheric plates and many associated landforms. Divergent boundaries move apart; convergent boundaries move toward one another; transform boundaries slide past. Plates include crust and uppermost mantle. They do not simply equal individual continents: one plate can carry both continental and oceanic areas. Earthquakes and much volcanism occur near boundaries, although not all volcanic activity is exactly on a plate edge. Mantle processes and forces including slab pull contribute to movement.",
 "A class can model boundaries with card pieces: separate them, bring them together and slide them side by side. The model shows relative movement rather than the full physics. Do not use every Cameroonian volcanic feature as proof of a present plate boundary: the Cameroon Volcanic Line requires more specific regional explanation.",
 "Identify relative movement before predicting the associated process. Convergence can involve subduction or continental collision, depending on plate types. Distinguish a plate from its crustal surface and from a country's political boundary.",[
 F("divergent boundary","a boundary where plates move apart","Model plates separate and new material can rise into the gap.","Divergence means plates necessarily collide head-on.","Moving apart is divergence; collision is convergence."),
 F("convergent boundary","a boundary where plates move toward one another","An oceanic plate descends beneath another plate in a model.","All convergence creates the same landform regardless of plate type.","Subduction and continental collision have different outcomes."),
 F("transform boundary","a boundary where plates slide past one another","Model plates move sideways alongside each other.","A transform boundary requires the plates to move directly apart.","Sideways relative sliding distinguishes the transform case."),
 F("lithospheric plate","a rigid piece of crust and uppermost mantle","A plate model includes both its surface crust and underlying rigid mantle.","Every plate is identical to exactly one continent.","Plate boundaries and continental outlines are not identical.")],prerequisites=[11,13])

INTRUSIONS=json.dumps('<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Cross-section: a dyke cuts layers, a sill follows them, lava lies above the surface" viewBox="0 0 340 220"><g stroke="currentColor" stroke-width="2"><path d="M10 65H330M10 110H330M10 155H330M10 195H330"/><path d="M90 195L125 65L139 65L104 195Z" fill="#b55a4b"/><rect x="139" y="103" width="150" height="14" fill="#b55a4b"/><path d="M125 65L160 40L208 65Z" fill="#b55a4b"/></g><g fill="currentColor" font-family="sans-serif" font-size="12"><text x="15" y="30">lava at surface</text><text x="15" y="95">rock layers</text><text x="155" y="95">sill follows a layer</text><text x="130" y="180">dyke cuts layers</text><text x="15" y="216">Schematic, not to scale</text></g></svg>')
unit(15,"Volcanicity: intrusive and extrusive features",
 "Volcanicity includes movement and emplacement of molten material in or onto Earth's crust. Magma remains below the surface; lava is magma erupted onto the surface. Intrusive features form below ground. A dyke cuts across existing layers; a sill lies along them. Extrusive features include lava flows and volcanic cones. Eruptions can also release ash and gases. Not all volcanic hazards are slow lava flows, and not every intrusion reaches the surface.",
 "Near Mount Cameroon, volcanic landforms can be discussed through maps and teacher-selected observations. This lesson is classroom preparation, not an invitation to approach an active vent. A section drawing distinguishes a sheet cutting layers from one following them. Classification depends on their relationship to the rock layers rather than only on the page's up/down direction.",
 "Ask whether the molten material stayed below ground or erupted. For a sheet intrusion, inspect whether it cuts across or follows the existing layers. Use correct terms for ash and gases, and keep physical landforms separate from the human effects of an eruption.",[
 F("magma","molten material beneath Earth's surface","Molten material occupies a chamber below a volcano.","All underground molten material is called surface lava.","Use magma below the surface and lava after eruption."),
 F("lava","molten material erupted onto the surface","Molten material flows over the land during an eruption.","Lava is only unheated sediment carried by a river.","Lava is erupted molten material, not ordinary river sediment."),
 F("dyke","a sheet intrusion cutting across existing layers","A molten sheet crosses older rock beds.","Every sheet intrusion that follows a bedding plane is a dyke.","Following bedding is characteristic of a sill; cutting across is a dyke."),
 F("sill","a sheet intrusion lying along existing layers","A molten sheet is emplaced between rock beds.","A sill is defined only by being drawn horizontally on the page.","Its relationship to the existing layers defines it, even if the layers are tilted.")],learn_figure=INTRUSIONS)

unit(16,"Volcanicity: benefits, hazards and human responses",
 "Volcanic areas can provide fertile weathered soils, rock materials, landscapes that attract visitors and geothermal opportunities under suitable conditions. They can also face lava, ash, gases and fast-moving hazards. A long-term resource benefit does not make an eruption safe. Risk depends on the hazard and people's exposure and vulnerability. Monitoring and official evacuation planning reduce some risks but do not guarantee precise predictions or eliminate danger.",
 "Communities near Mount Cameroon may benefit from landscapes and soils while still needing to respect hazard information. Weathering can improve some soils over time; fresh lava is not instant farmland. Tourism income also depends on access, services and safety. Avoid presenting attractive scenery as a reason to disregard local warnings.",
 "Separate the natural process, a possible resource and the conditions required to use it. Compare short-term damage with long-term benefits without cancelling one out against the other. For real events follow local authorities and trained responders rather than treating a school exercise as an operational forecast.",[
 F("soil benefit","a possible long-term resource from weathered volcanic material","Farming uses a suitable soil developed over time on volcanic parent material.","Fresh lava is immediately safe fertile farmland.","Soil development takes time and does not remove eruption hazards."),
 F("volcanic hazard","a potentially damaging volcanic process","Ash, gases or lava threaten an exposed settlement.","Only slow lava can be hazardous in an eruption.","Ash, gases and other volcanic processes can also cause harm."),
 F("exposure","people and assets being located where a hazard can affect them","Homes are situated in an area a volcanic process may reach.","A hazard matters only after it has already destroyed every building.","Exposure concerns what could be affected, not only damage already observed."),
 F("risk reduction","actions intended to reduce losses without guaranteeing complete safety","A community prepares an official evacuation plan and listens to monitoring information.","An evacuation plan guarantees that no volcanic harm can ever occur.","Preparation can reduce losses but cannot make every outcome certain.")])

unit(17,"Earthquakes: processes, impacts and preparedness",
 "An earthquake is shaking caused by a sudden release of energy, commonly involving movement on a fault. The focus is the origin within Earth; the epicentre is directly above it on the surface. Effects include ground shaking and possible damage, landslides or other secondary hazards depending on the setting. Magnitude measures event size; intensity describes observed effects at a place. Preparedness and safer buildings can reduce losses. A school lesson cannot predict the precise time of the next damaging earthquake.",
 "A classroom can practise recognised protective actions before an event. If indoors when shaking begins, drop, cover your head and neck under a nearby sturdy table where possible, and hold on; stay clear of windows. Do not rush down stairs during shaking. Actual emergency instructions must be adapted by responsible local authorities to the building and setting.",
 "Distinguish the cause, the location terms and the measured effects. Do not say that a single magnitude gives identical damage everywhere: distance, ground and buildings matter. Practise the school's plan with an adult. During a real emergency, follow responsible local instructions and trained responders.",[
 F("focus","the origin of an earthquake within Earth","A diagram marks where fault movement releases energy below ground.","The focus is always the point directly above the earthquake on the surface.","The surface point above the focus is the epicentre."),
 F("epicentre","the surface point directly above the focus","A map marks the position above the underground origin.","The epicentre is necessarily the deepest point inside the core.","Epicentre is a surface location, not a core depth."),
 F("intensity","the observed shaking effects at a particular place","Two towns report different damage from the same event.","One event must produce identical observed effects in every town.","Local ground, distance and buildings can change observed intensity."),
 F("protective action","prepared behaviour reducing exposure to falling objects during shaking","An indoor pupil takes nearby sturdy cover, protects the head and holds on away from windows.","Running down stairs during shaking is the recommended first indoor action.","USGS guidance advises staying indoors during shaking and using Drop, Cover and Hold On rather than rushing outside.")])

